PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?year
WHERE {
  GRAPH <hydroturtle/quadica> {
    # Step 1: Get all catchments (at least partially in Germany)
    ?catchment a envthes:30212 ;
               hyobs:fractionAreaInGermany ?fraction .
    # Step 2: Get all DischargeMedian observations for these catchments
    ?observation a sosa:Observation ;
                 sosa:hasFeatureOfInterest ?catchment ;
                 sosa:observedProperty hyobs:DischargeMedian ;
                 sosa:resultTime ?year ;
                 sosa:hasResult ?quantity .
    ?quantity qudt:numericValue ?value .
  }
}
GROUP BY ?year
HAVING (
  MEDIAN(?value) < 
    {
      SELECT (MEDIAN(?allValue) AS ?longTermMedian)
      WHERE {
        GRAPH <hydroturtle/quadica> {
          ?catchment a envthes:30212 ;
                     hyobs:fractionAreaInGermany ?fraction .
          ?observation a sosa:Observation ;
                       sosa:hasFeatureOfInterest ?catchment ;
                       sosa:observedProperty hyobs:DischargeMedian ;
                       sosa:hasResult ?quantity .
          ?quantity qudt:numericValue ?allValue .
        }
      }
    }
)

actual_sparql:
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa:  <http://www.w3.org/ns/sosa/>
PREFIX qudt:  <http://qudt.org/schema/qudt/>
PREFIX xsd:   <http://www.w3.org/2001/XMLSchema#>

SELECT ?year ?nationalMedianQ ?longTermMedianQ
WHERE {
  GRAPH <hydroturtle/quadica> 
  {
    {
      SELECT ?year (AVG(xsd:decimal(?val)) AS ?nationalMedianQ)
      WHERE {
        ?obs a sosa:Observation ;
            sosa:observedProperty hyobs:DischargeMedian ;
            sosa:resultTime ?t ;
            sosa:hasResult ?res .
        ?res qudt:numericValue ?val .
        BIND(YEAR(?t) AS ?year)
      }
      GROUP BY ?year
    }
    {
      SELECT (AVG(xsd:decimal(?val2)) AS ?longTermMedianQ)
      WHERE {
        ?obs2 a sosa:Observation ;
              sosa:observedProperty hyobs:DischargeMedian ;
              sosa:hasResult ?res2 .
        ?res2 qudt:numericValue ?val2 .
      }
    }

    FILTER(?nationalMedianQ < ?longTermMedianQ)
  }
}
ORDER BY ?year

